import { api, isMockMode } from '../lib/api.js';
import { calculatePricing, feeLabel } from '../lib/pricing.js';
import { clock, dateParts, escapeHtml, longDate, money, secondsLeft } from '../lib/format.js';
import { icon, setTitle, toast } from '../lib/dom.js';

export async function eventView(slug) {
  const event = await api.getEvent(slug);
  if (!event) throw new Error('That event could not be found.');
  setTitle(event.name);
  const date = dateParts(event.startsAt);
  const firstAvailable = event.tiers.find((tier) => tier.remaining > 0);

  return {
    meta: { section: 'public' },
    html: `
      <main id="main" tabindex="-1" style="--event-accent:${event.accent}">
        <a href="/events" class="event-back" data-link>${icon('back')} All events</a>
        <section class="event-hero">
          <div class="event-hero__date"><span>${date.month}</span><strong>${date.day}</strong><small>${date.year}</small></div>
          <div class="event-hero__poster"><img src="${event.image}" alt="Poster artwork for ${escapeHtml(event.name)}"><span>${escapeHtml(event.code)} / LAGOS</span></div>
          <div class="event-hero__title">
            <p class="kicker">${escapeHtml(event.eyebrow)}</p>
            <h1>${escapeHtml(event.name)}</h1>
            <p>${escapeHtml(event.description)}</p>
          </div>
          <dl class="event-hero__facts">
            <div><dt>${icon('calendar')} Date & time</dt><dd>${escapeHtml(longDate(event.startsAt))}<small>${escapeHtml(event.doors)}</small></dd></div>
            <div><dt>${icon('pin')} Venue</dt><dd>${escapeHtml(event.venue)}<small>Lagos, Nigeria</small></dd></div>
          </dl>
        </section>

        <section class="event-body page-shell">
          <div class="event-notes">
            <div class="section-number"><span>01</span><p class="kicker">BEFORE YOU BUY</p></div>
            <h2>One tier. One order. One named pass for each person.</h2>
            <p>Choose everyone’s ticket tier together, then add a name and email for each attendee. Each person gets their own QR ticket; the purchaser keeps a full set.</p>
            <ul class="plain-list">
              <li>${icon('check')} Ticket hold begins when checkout is ready for Paystack.</li>
              <li>${icon('check')} All sales are final, apart from the stated exceptions.</li>
              <li>${icon('check')} The QR is valid for one successful check-in.</li>
            </ul>
            <div class="event-callout"><span>DON’T GUESS</span><p>If you are buying for friends, use the names they will show at the door. You cannot change attendees yourself after payment in this version.</p></div>
          </div>

          <aside class="checkout" aria-labelledby="checkout-title">
            <header class="checkout__head"><div><p class="kicker">BOX OFFICE</p><h2 id="checkout-title">Choose your ticket</h2></div><span class="secure-note">${icon('ticket')} NGN</span></header>
            <div class="checkout-step" data-ticket-step>
              <div class="tier-list" role="radiogroup" aria-label="Ticket tier">
                ${event.tiers.map((tier) => tierRow(tier, tier.id === firstAvailable?.id)).join('')}
              </div>
              ${firstAvailable ? `
                <div class="quantity-line">
                  <div><span class="field-label">How many?</span><small data-remaining>${firstAvailable.remaining} left at this price</small></div>
                  <div class="stepper" aria-label="Ticket quantity">
                    <button type="button" data-quantity="minus" aria-label="Remove one ticket">${icon('minus')}</button>
                    <output data-quantity-output aria-live="polite">1</output>
                    <button type="button" data-quantity="plus" aria-label="Add one ticket">${icon('plus')}</button>
                  </div>
                </div>
                <div class="checkout-total checkout-total--compact">
                  <span>Estimated total</span><strong data-estimated-total>${money(calculatePricing(firstAvailable.priceMinor, 1, event.fee).totalMinor)}</strong>
                </div>
                <button class="button button--accent button--wide" type="button" data-continue>Continue with 1 ${escapeHtml(firstAvailable.name)} ticket ${icon('arrow')}</button>
                <p class="microcopy">No inventory is held until you continue to Paystack.</p>` : '<div class="sold-note"><strong>Every tier is sold out.</strong><p>There are no tickets to reserve right now.</p></div>'}
            </div>

            <form class="checkout-form" data-checkout-form hidden novalidate>
              <div class="form-progress"><span class="is-current">1 Details</span><span>2 Review</span><span>3 Pay</span></div>
              <section class="form-section">
                <div class="form-section__head"><span>01</span><div><h3>Purchaser</h3><p>Where should we send the complete order?</p></div></div>
                <label>Full name<input name="buyer-name" autocomplete="name" required maxlength="100" placeholder="e.g. Nneka Obi"></label>
                <div class="field-pair">
                  <label>Email<input name="buyer-email" type="email" autocomplete="email" required placeholder="you@example.com"></label>
                  <label>Phone<input name="buyer-phone" type="tel" autocomplete="tel" required placeholder="0801 234 5678" inputmode="tel"></label>
                </div>
              </section>
              <section class="form-section">
                <div class="form-section__head"><span>02</span><div><h3>Attendees</h3><p>Each person receives their own named ticket.</p></div></div>
                <div data-attendee-fields></div>
              </section>
              <section class="form-section review-section">
                <div class="form-section__head"><span>03</span><div><h3>Review</h3><p>Paystack will handle the card or transfer.</p></div></div>
                <div class="price-ledger" data-price-ledger></div>
                <label class="check-line"><input type="checkbox" name="terms" required><span>I accept the <a href="/terms" data-link>ticket terms</a>. Sales are final except for cancelled events, duplicate charges or confirmed payment/platform errors.</span></label>
                <div class="form-error" data-form-error role="alert" hidden></div>
                <button class="button button--ink button--wide button--pay" type="submit" data-pay-button>Reserve for 15 minutes & continue ${icon('arrow')}</button>
                <button class="text-button" type="button" data-change-selection>← Change tier or quantity</button>
              </section>
            </form>
          </aside>
        </section>
      </main>
      <div class="payment-layer" data-payment-layer hidden></div>`,
    mount: () => mountCheckout(event, firstAvailable),
  };
}

function tierRow(tier, checked) {
  const sold = tier.remaining < 1;
  return `<label class="tier-row ${sold ? 'tier-row--sold' : ''}">
    <input type="radio" name="tier" value="${tier.id}" ${checked ? 'checked' : ''} ${sold ? 'disabled' : ''}>
    <span class="tier-row__select" aria-hidden="true"></span>
    <span class="tier-row__copy"><strong>${escapeHtml(tier.name)}</strong><small>${escapeHtml(tier.description)}</small></span>
    <span class="tier-row__price"><strong>${money(tier.priceMinor)}</strong>${sold ? '<small>SOLD OUT</small>' : `<small>${tier.remaining} remain</small>`}</span>
  </label>`;
}

function mountCheckout(event, initialTier) {
  if (!initialTier) return;
  let selectedTier = initialTier;
  let quantity = 1;
  let idempotencyKey = crypto.randomUUID();
  let paymentTimer;
  let statusToken;
  const ticketStep = document.querySelector('[data-ticket-step]');
  const form = document.querySelector('[data-checkout-form]');
  const attendeeFields = document.querySelector('[data-attendee-fields]');
  const ledger = document.querySelector('[data-price-ledger]');
  const errorBox = document.querySelector('[data-form-error]');
  const layer = document.querySelector('[data-payment-layer]');

  const pricing = () => calculatePricing(selectedTier.priceMinor, quantity, event.fee);

  function updateSummary() {
    document.querySelector('[data-quantity-output]').textContent = quantity;
    document.querySelector('[data-remaining]').textContent = `${selectedTier.remaining} left at this price`;
    document.querySelector('[data-estimated-total]').textContent = money(pricing().totalMinor);
    document.querySelector('[data-continue]').innerHTML = `Continue with ${quantity} ${escapeHtml(selectedTier.name)} ticket${quantity === 1 ? '' : 's'} ${icon('arrow')}`;
  }

  function renderAttendees() {
    attendeeFields.innerHTML = Array.from({ length: quantity }, (_, index) => `
      <fieldset class="attendee-fieldset">
        <legend><span>Ticket ${index + 1}</span> Who is using this ticket?</legend>
        <div class="field-pair">
          <label>Attendee name<input name="attendee-name-${index}" autocomplete="name" required maxlength="100" placeholder="Full name"></label>
          <label>Attendee email<input name="attendee-email-${index}" type="email" autocomplete="email" required placeholder="name@example.com"></label>
        </div>
      </fieldset>`).join('');
    const price = pricing();
    ledger.innerHTML = `
      <div><span>${quantity} × ${escapeHtml(selectedTier.name)}</span><strong>${money(price.subtotalMinor)}</strong></div>
      <div><span>${feeLabel(event.fee)}</span><strong>${money(price.feeTotalMinor)}</strong></div>
      <div class="price-ledger__total"><span>Total due</span><strong>${money(price.totalMinor)}</strong></div>`;
  }

  function chooseTier(id) {
    selectedTier = event.tiers.find((tier) => tier.id === id);
    quantity = Math.min(quantity, selectedTier.maxPerOrder, selectedTier.remaining);
    updateSummary();
  }

  document.querySelectorAll('input[name="tier"]').forEach((radio) => radio.addEventListener('change', () => chooseTier(radio.value)));
  document.querySelector('[data-quantity="minus"]').addEventListener('click', () => { quantity = Math.max(1, quantity - 1); updateSummary(); });
  document.querySelector('[data-quantity="plus"]').addEventListener('click', () => {
    const max = Math.min(selectedTier.maxPerOrder, selectedTier.remaining);
    if (quantity >= max) return toast(`You can choose up to ${max} ${selectedTier.name} ticket${max === 1 ? '' : 's'} in this order.`, 'warning');
    quantity += 1; updateSummary();
  });
  document.querySelector('[data-continue]').addEventListener('click', () => {
    renderAttendees();
    ticketStep.hidden = true;
    form.hidden = false;
    form.querySelector('input')?.focus();
  });
  document.querySelector('[data-change-selection]').addEventListener('click', () => {
    form.hidden = true; ticketStep.hidden = false; ticketStep.scrollIntoView({ behavior: 'smooth', block: 'center' });
  });

  form.addEventListener('submit', async (submitEvent) => {
    submitEvent.preventDefault();
    errorBox.hidden = true;
    if (!form.checkValidity()) {
      form.reportValidity();
      errorBox.textContent = 'Check the highlighted details and accept the ticket terms.';
      errorBox.hidden = false;
      return;
    }
    const values = new FormData(form);
    const button = form.querySelector('[data-pay-button]');
    button.disabled = true;
    button.innerHTML = '<span class="button-spinner" aria-hidden="true"></span> Reserving your tickets…';
    try {
      const result = await api.initiateOrder({
        eventSlug: event.slug, tierId: selectedTier.id, quantity,
        buyer: { fullName: values.get('buyer-name'), email: values.get('buyer-email'), phone: values.get('buyer-phone') },
        attendees: Array.from({ length: quantity }, (_, index) => ({ fullName: values.get(`attendee-name-${index}`), email: values.get(`attendee-email-${index}`) })),
        termsAccepted: values.get('terms') === 'on', idempotencyKey,
      });
      statusToken = result.statusAccessToken;
      sessionStorage.setItem('tixora-status-token', statusToken);
      sessionStorage.setItem('tixora-order-reference', result.orderReference);
      if (!isMockMode && result.authorizationUrl) {
        window.location.assign(result.authorizationUrl);
        return;
      }
      showDemoPayment(result);
    } catch (error) {
      errorBox.textContent = error.message;
      errorBox.hidden = false;
      button.disabled = false;
      button.innerHTML = `Reserve for 15 minutes & continue ${icon('arrow')}`;
      if (error.code === 'sold_out') idempotencyKey = crypto.randomUUID();
    }
  });

  function showDemoPayment(result) {
    layer.hidden = false;
    layer.innerHTML = `
      <div class="payment-sheet" role="dialog" aria-modal="true" aria-labelledby="payment-title">
        <div class="payment-sheet__brand"><strong>TIXORA <span>×</span> PAYSTACK</strong><button type="button" data-close-payment aria-label="Return to checkout">${icon('close')}</button></div>
        <div class="payment-sheet__body">
          <p class="kicker">TEST CHECKOUT / NO MONEY MOVES</p>
          <h2 id="payment-title">Pay ${money(result.pricing.totalMinor)}</h2>
          <p>Your ${quantity} ${escapeHtml(selectedTier.name)} ticket${quantity === 1 ? '' : 's'} ${quantity === 1 ? 'is' : 'are'} held for <strong data-hold-clock>15:00</strong>.</p>
          <div class="payment-methods" role="group" aria-label="Demo payment method">
            <button class="payment-method is-active" type="button" data-method="card"><span>01</span><strong>Card</strong><small>Instant test approval</small></button>
            <button class="payment-method" type="button" data-method="bank_transfer"><span>02</span><strong>Bank transfer</strong><small>Simulate transfer received</small></button>
          </div>
          <div class="test-instruction"><span>TEST MODE</span><p data-method-copy>No card number is needed. Approve the test charge to exercise the verified-payment, ticket and email flow.</p></div>
          <button class="button button--accent button--wide" type="button" data-complete-payment>Approve test card payment ${icon('arrow')}</button>
          <p class="payment-sheet__reference">Order ${escapeHtml(result.orderReference)} · Secured on the server</p>
        </div>
      </div>`;
    let method = 'card';
    layer.querySelectorAll('[data-method]').forEach((button) => button.addEventListener('click', () => {
      method = button.dataset.method;
      layer.querySelectorAll('[data-method]').forEach((item) => item.classList.toggle('is-active', item === button));
      layer.querySelector('[data-method-copy]').textContent = method === 'card'
        ? 'No card number is needed. Approve the test charge to exercise the verified-payment, ticket and email flow.'
        : 'This simulates Paystack confirming a bank transfer by webhook while the inventory hold is active.';
      layer.querySelector('[data-complete-payment]').innerHTML = `${method === 'card' ? 'Approve test card payment' : 'Mark demo transfer received'} ${icon('arrow')}`;
    }));
    layer.querySelector('[data-close-payment]').addEventListener('click', () => { layer.hidden = true; clearInterval(paymentTimer); });
    layer.querySelector('[data-complete-payment]').addEventListener('click', async (clickEvent) => {
      const button = clickEvent.currentTarget;
      button.disabled = true;
      button.innerHTML = '<span class="button-spinner"></span> Paystack webhook received…';
      try {
        await api.completeDemoPayment(statusToken, method);
        clearInterval(paymentTimer);
        history.pushState({}, '', `/order/status#${statusToken}`);
        window.dispatchEvent(new PopStateEvent('popstate'));
      } catch (error) {
        button.disabled = false;
        button.textContent = error.message;
      }
    });
    const tick = () => {
      const left = secondsLeft(result.holdExpiresAt);
      const output = layer.querySelector('[data-hold-clock]');
      if (output) output.textContent = clock(left);
      if (!left) clearInterval(paymentTimer);
    };
    tick(); paymentTimer = setInterval(tick, 1000);
    layer.querySelector('[data-complete-payment]').focus();
  }

  updateSummary();
  return () => clearInterval(paymentTimer);
}
